import{_ as e,o as i,c as n,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armadura y protección","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/armor-and-protection.md","filePath":"es/guide/combat/armor-and-protection.md"}'),t={name:"es/guide/combat/armor-and-protection.md"};function o(s,a,d,l,c,p){return i(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="armor-and-protection" tabindex="-1">Armadura y protección <a class="header-anchor" href="#armor-and-protection" aria-label="Enlace permanente a &quot;Armadura y protección&quot;">​</a></h1><ul><li><strong>Estado del diseño:</strong> Aceptado para cobertura y desgaste de piezas compartidas; Propuesto para interacciones ampliadas entre materiales.</li><li><strong>Implementación:</strong> Adaptación de armadura heredada de Stage 2A; sin nueva simulación de materiales por capas.</li><li><strong>Disponibilidad:</strong> aquí no se establece ningún comportamiento nuevo en vivo; no se ha inspeccionado la configuración actual.</li><li><strong>Verificación:</strong> documentación revisada el 2026-10-08; sin nueva prueba de juego. El alcance de la evidencia existente figura en <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">estado del combate</a>.</li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La armadura protege la región realmente alcanzada; las mangas y las perneras compartidas conservan una durabilidad compartida.</li><li>Las ventajas de los materiales, las capas y el mantenimiento son ampliaciones propuestas, no una tabla de resistencias definitiva.</li><li>La calidad mejora el rendimiento útil sin eliminar el riesgo de perder equipo.</li></ul><h2 id="protection-depends-on-where-the-hit-lands" tabindex="-1">La protección depende de dónde impacte el golpe <a class="header-anchor" href="#protection-depends-on-where-the-hit-lands" aria-label="Enlace permanente a &quot;La protección depende de dónde impacte el golpe&quot;">​</a></h2><p>La armadura cubre regiones concretas del cuerpo. Las mangas protegen ambos brazos mediante una única pieza compartida, y las perneras protegen ambas piernas; su durabilidad no se divide en piezas imaginarias izquierda y derecha. Una región descubierta no hace que el servidor vuelva a sortear el impacto en otro lugar.</p><h2 id="materials-and-condition" tabindex="-1">Materiales y estado <a class="header-anchor" href="#materials-and-condition" aria-label="Enlace permanente a &quot;Materiales y estado&quot;">​</a></h2><p>La dirección propuesta da a las placas, la malla, el cuero y la protección acolchada o por capas ventajas y costes diferentes. Una placa podría detener un corte y transmitir el impacto. La magnitud, los enfrentamientos entre materiales y las reglas de capas siguen sin resolverse; esto no es una tabla de resistencias actual.</p><p>El desgaste del filo, las deformaciones y las correas y costuras dañadas podrían dar utilidad táctica al mantenimiento. Blacksmithing y Tailoring conectan el conocimiento del equipo con la reparación, mientras que la calidad del objeto describe su rendimiento y su capacidad para conservar su función. Una calidad alta no elimina el riesgo aceptado de una pérdida significativa de equipo.</p><p><a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">Especificación completa de armadura</a> · <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a>.</p><p><a href="/Syrolands-Public/es/guide/combat/overview.html">Volver al resumen de combate</a></p>',11)])])}const g=e(t,[["render",o]]);export{u as __pageData,g as default};
